**mostFrequentWord(text)**

Write `mostFrequentWord(text)` with a `Map`: the most common word, lower-cased. On a tie, return the word that appeared first. Empty text gives `""`.

```js
function mostFrequentWord(text) {
  const counts = new Map();
  // TODO
  return "";
}
```

notes.back:
// Why: A Map iterates in insertion order, so a strict > keeps the first word on a tie.
// `counts.get(word) ?? 0` starts a new word at zero.
// Docs: https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Map
function mostFrequentWord(text) {
  const counts = new Map();
  for (const word of text.toLowerCase().split(/\s+/).filter(Boolean)) {
    counts.set(word, (counts.get(word) ?? 0) + 1);
  }
  let best = "";
  let bestCount = 0;
  for (const [word, count] of counts) {
    if (count > bestCount) {
      best = word;
      bestCount = count;
    }
  }
  return best;
}

